#include <bits/stdc++.h>

using namespace std;

int main() {
    // input
    int n;
    cin >> n;
    vector<int> a(n);
    for (auto &e : a) {
        cin >> e;
    }

    int answer = 0;
    while (true) {
        // sort
        sort(a.begin(), a.end(), greater());

        // check condition
        if (a[0] == 0 or a[1] == 0) {
            break;
        }

        // apply
        a[0] -= 1;
        a[1] -= 1;
        ++answer;
    }

    // output
    cout << answer << endl;
}

#include <iostream>
#include <algorithm>

using namespace std;

int main() {
    int N;
    cin >> N;
    int sum_A = 0, max_A = 0;
    for (int i = 0; i < N; ++i) {
        int A;
        cin >> A;
        // A の合計と A の最大値を更新
        sum_A += A;
        max_A = max(A, max_A);
    }
    // 答えは min(合計 / 2, 合計 - 最大値)
    cout << min(sum_A / 2, sum_A - max_A) << endl;
    return 0;
}
